create or replace function public.map_network_nearby_v1(p_lat double precision, p_lng double precision, p_radius_m integer default 30000, p_limit integer default 250, p_category text default null, p_search text default null, p_amenity_names text[] default '{}') returns table(location_id uuid, place_id uuid, name text, category text, address text, city text, state text, postal_code text, latitude double precision, longitude double precision, distance_meters double precision, source text, source_dataset text, source_external_id text, is_verified boolean, rating numeric, review_count integer, cleanliness_pct numeric, verification_confidence numeric, amenities jsonb, fixtures jsonb, brand text, operator_name text, osm_tags jsonb) language sql stable set search_path to 'public' as $$ with base as (select l.id,l.place_type,l.name,l.address,l.city,l.state,l.postal_code,l.latitude,l.longitude,l.source,l.source_dataset,l.source_external_id,l.source_metadata,l.rating as l_rating,l.review_count as l_review_count,l.cleanliness_pct,l.verification_confidence,p.id as place_id,p.category as p_category,p.rating as p_rating,p.review_count as p_review_count,p.is_verified as p_is_verified,p.name as place_name,6371000.0*2*asin(sqrt(power(sin(radians(l.latitude-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(l.latitude))*power(sin(radians(p.longitude-p_lng)/2),2))) as dist from locations l left join places p on p.location_id=l.id and p.is_active=true where l.is_active=true and l.latitude is not null and l.longitude is not null and l.latitude between p_lat-(p_radius_m/111320.0) and p_lat+(p_radius_m/111320.0) and l.longitude between p_lng-(p_radius_m/(111320.0*greatest(cos(radians(p_lat)),0.2))) and p_lng+(p_radius_m/(111320.0*greatest(cos(radians(p_lat)),0.2))) and (p_category is null or coalesce(p.category,l.place_type)=p_category) and (p_search is null or p_search='' or coalesce(l.name,'') ilike '%'||p_search||'%' or coalesce(p.name,'') ilike '%'||p_search||'%' or coalesce(l.address,'') ilike '%'||p_search||'%' or coalesce(l.city,'') ilike '%'||p_search||'%' or coalesce(l.state,'') ilike '%'||p_search||'%' or coalesce(l.postal_code,'') ilike '%'||p_search||'%' or coalesce(l.source_metadata->>'brand','') ilike '%'||p_search||'%' or coalesce(l.source_metadata->>'brand_name','') ilike '%'||p_search||'%' or coalesce(l.source_metadata->>'operator','') ilike '%'||p_search||'%' or coalesce(l.source_metadata->>'operator_name','') ilike '%'||p_search||'%')), ranked as (select * from base where dist<=p_radius_m order by dist limit greatest(1,least(p_limit,500))), amen as (select la.location_id,jsonb_agg(distinct jsonb_build_object('name',a.name,'category',a.category)) items from location_amenities la join amenities a on a.id=la.amenity_id group by la.location_id), fx as (select lf.location_id,jsonb_build_object('stalls',lf.stalls,'urinals',lf.urinals,'sinks',lf.sinks,'hand_dryers',lf.hand_dryers,'changing_tables',lf.changing_tables,'showers',lf.showers) items from location_fixtures lf) select r.id,r.place_id,coalesce(r.place_name,r.name),coalesce(r.p_category,r.place_type,'service'),r.address,r.city,r.state,r.postal_code,r.latitude,r.longitude,r.dist,r.source,r.source_dataset,r.source_external_id,coalesce(r.p_is_verified,false),coalesce(r.p_rating,r.l_rating,0),coalesce(r.p_review_count,r.l_review_count,0),r.cleanliness_pct,r.verification_confidence,coalesce(a.items,'[]'::jsonb),coalesce(f.items,'{}'::jsonb),coalesce(r.source_metadata->>'brand',r.source_metadata->>'brand_name'),coalesce(r.source_metadata->>'operator',r.source_metadata->>'operator_name'),coalesce(r.source_metadata->'osm_tags','{}'::jsonb) from ranked r left join amen a on a.location_id=r.id left join fx f on f.location_id=r.id where cardinality(p_amenity_names)=0 or exists (select 1 from location_amenities la join amenities aa on aa.id=la.amenity_id where la.location_id=r.id and aa.name=any(p_amenity_names)) order by r.dist; $$;
